import {escapeHTML as esc,safeURL,mergeEditions,refreshEditions,latestFor,localDay,readStorage,scheduleReview,cleanLearningState,importLibrary,validateHeadlines,refreshHeadlines} from './learning-core.mjs';
import {validateCollection} from './daily-view.mjs';
const KEY='knowledge-pill-learning-v2', OLD='knowledge-pill-daily-v1';
let storage;try{storage=window.localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw Error('Storage unavailable');}};}
const legacy=readStorage(storage,'knowledge-pill-v1',{}), saved=readStorage(storage,KEY,{}), oldDaily=readStorage(storage,OLD,{});
const state={...cleanLearningState({...legacy,...saved}),topic:'All topics',step:0,showAnswer:false,quizChoice:null};
let headlines=null,guides=[],briefings=[],foundations=[],packets=[],view='today',selectedId=null,sync={state:'loading',message:'Checking for new editions…'},partial=[];
const $=s=>document.querySelector(s), te=()=>state.language==='te', tr=(en,tel)=>te()?tel:en;
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',book:'M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H4ZM20 3h-4a3 3 0 0 0-3 3v15a4 4 0 0 1 4-2h3Z',save:'M6 3h12v18l-6-4-6 4Z',refresh:'M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0 1 13-3l2 3M4 16l2 3a8 8 0 0 0 13-3',arrow:'M5 12h14M13 6l6 6-6 6',check:'m5 12 4 4L19 6',settings:'M4 6h16M4 12h16M4 18h16M9 3v6M15 9v6M8 15v6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',external:'M14 3h7v7M10 14 21 3M10 3H3v18h18v-7',close:'m5 5 14 14M19 5 5 19',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`;
const paragraph=s=>String(s||'').split(/\n+/).filter(Boolean).map(x=>`<p>${esc(x)}</p>`).join('');
const dateLabel=(d,full=false)=>{if(!d)return tr('Publication date not listed','ప్రచురణ తేదీ లేదు');const value=/^\d{4}-\d{2}-\d{2}$/.test(d)?d+'T12:00:00Z':d;return new Intl.DateTimeFormat(te()?'te-IN':'en-US',{month:'short',day:'numeric',...(full?{year:'numeric'}:{}),timeZone:'UTC'}).format(new Date(value));};
function persist(){try{storage.setItem(KEY,JSON.stringify({language:state.language,bookmarks:state.bookmarks,reviews:state.reviews,notes:state.notes}));}catch{toast(tr('Storage is unavailable. Your changes last for this session.','Storage అందుబాటులో లేదు. ఈ sessionలో మాత్రమే మార్పులు ఉంటాయి.'));}}
function savePackets(){try{storage.setItem(OLD,JSON.stringify({packets,progress:oldDaily.progress||{}}));}catch{toast('Could not save editions on this device. They remain readable this session.');}}
function toast(message){$('#toast')?.remove();const n=document.createElement('div');n.id='toast';n.className='toast';n.setAttribute('role','status');n.textContent=message;document.body.append(n);setTimeout(()=>n.remove(),5000);}
function normalizeFoundation(p){const c=p[state.language];return {...p,type:'foundation',date:p.created_at,title:c.title,summary:c.summary,story:c.analogy,bridge:tr('This is an analogy to help you remember the concept.','ఇది విషయం గుర్తుంచుకోవడానికి ఇచ్చిన పోలిక.'),concepts:[{heading:tr('The idea, simply','సులభంగా అర్థం చేసుకుందాం'),body:c.explain}],example:null,remember:c.answer,exercise:{prompt:c.exercise,answer:c.answer},recallQuestion:c.recall,limits:[p.evidence_note],sources:p.sources.map(s=>({...s,publisher:s.title.split('—')[0],note:''}))};}
function normalizeGuide(p){return {...p,...p[state.language],type:'guide'};}
function normalizeDaily(p,kind){const k=p.knowledge,n=p.news;const refs=kind==='knowledge'?k.source_ids:[...new Set(n.items.flatMap(x=>x.source_ids))];return {id:`${p.id}:${kind}`,packetId:p.id,type:'daily',pillKind:kind,topic:p.topic,language:p.language,date:p.date,minutes:7,kind:kind==='knowledge'?tr('Knowledge pill','జ్ఞాన pill'):tr('AI news pill','AI వార్తల pill'),title:kind==='knowledge'?k.title:n.title,summary:kind==='knowledge'?k.summary:n.overview,story:kind==='knowledge'?k.story:n.overview,bridge:kind==='knowledge'?k.connection:tr('Read the development, its significance and its limits. Original publication dates appear with each source.','విషయం, దాని ఉపయోగం, పరిమితులు చదవండి. అసలు ప్రచురణ తేదీలు sources దగ్గర ఉన్నాయి.'),concepts:kind==='knowledge'?[{heading:tr('How it works','ఎలా పనిచేస్తుంది'),body:k.explanation}]:n.items.map(x=>({heading:x.headline,body:x.what_happened+'\n'+x.why_it_matters,source_ids:x.source_ids})),example:kind==='knowledge'?{title:tr('Put it to work','ఆచరణలో ఉపయోగించండి'),body:k.application}:null,remember:kind==='knowledge'?k.answer:n.items.map(x=>x.takeaway).join('\n'),exercise:{prompt:(kind==='knowledge'?k:n).exercise,answer:(kind==='knowledge'?k:n).answer},recallQuestion:(kind==='knowledge'?k:n).question,limits:kind==='knowledge'?[k.limits]:[tr('These are generated drafts. Check important claims against the linked sources.','ఇవి generated drafts. ముఖ్యమైన విషయాలు sourcesతో సరిచూడండి.')],sources:p.sources.filter(s=>refs.includes(s.id)).map(s=>({...s,date:s.published_at,note:s.evidence_type.replaceAll('_',' ')})),evidence_note:tr('Generated draft. Structure and source references are checked automatically; factual accuracy and language still need reader review.','Generated draft. Structure, source references ఆటోమేటిక్‌గా check చేస్తాం; నిజాలు, భాష ఇంకా పరిశీలించాలి.'),writer_model:p.writer_model,created_at:p.created_at};}
const normalizeBrief=p=>({...p,...p[state.language],type:'brief',pillKind:'news'});
function catalog(){return [...briefings.map(normalizeBrief),...guides.map(normalizeGuide),...foundations.map(normalizeFoundation),...packets.filter(p=>p.language===state.language).sort((a,b)=>b.date.localeCompare(a.date)).flatMap(p=>[normalizeDaily(p,'knowledge'),...(p.news.items.length?[normalizeDaily(p,'news')]:[])])];}
function current(){return catalog().find(p=>p.id===selectedId);}
function dueCount(){return catalog().filter(p=>state.reviews[p.id]?.due&&Date.parse(state.reviews[p.id].due)<=Date.now()).length;}
function nav(viewName){location.hash=viewName==='today'?'#today':'#'+viewName;}
function openPill(id){location.hash='#pill/'+encodeURIComponent(id);}
function parseRoute(){const hash=location.hash.slice(1);view=hash.startsWith('pill/')?'reader':['news','explore','saved','review','settings'].includes(hash)?hash:'today';try{selectedId=view==='reader'?decodeURIComponent(hash.slice(5)):null;}catch{selectedId=null;}state.step=0;state.showAnswer=false;state.quizChoice=null;render();window.scrollTo({top:0,behavior:'instant'});$('#page-title')?.focus({preventScroll:true});}
function statusHTML(){return `<span class="sync-status ${sync.state==='error'?'offline':''}" id="sync-status">${sync.state==='loading'?'<span class="spinner"></span>':icon(sync.state==='error'?'clock':'check')}${esc(sync.message)}</span>`;}
function shell(content){return `<aside class="sidebar"><a class="brand" href="#today"><span class="brand-mark" aria-hidden="true"></span><span>Knowledge<span class="brand-light">Pill</span></span></a><p class="side-caption">A LITTLE LEARNING. EVERY DAY.</p><nav class="main-nav" aria-label="Main navigation">${[['today','home',tr('Daily dose','రోజువారీ pills')],['news','spark',tr('AI news','AI వార్తలు')],['explore','grid',tr('Explore pills','Pills చూడండి')],['saved','save',tr('Saved pills','దాచిన pills')],['review','refresh',tr('Recall practice','గుర్తు చేసుకోండి')]].map(([id,ico,label])=>`<a href="#${id}" class="nav-link ${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${id==='review'&&dueCount()?`<span class="nav-count">${dueCount()}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="small-label">BUILT THROUGH CURIOSITY</div><p>One useful idea.<br>Yours to understand.</p><a class="nav-link" href="lab.html">${icon('book')}<span>Week 5 lab</span>${icon('external')}</a><a class="nav-link ${view==='settings'?'active':''}" href="#settings">${icon('settings')}<span>${tr('Library settings','Library settings')}</span></a><a class="made-by" href="https://github.com/DRKREDDY5/Knowledge-Pill" target="_blank" rel="noopener noreferrer">Built by Rushikeshava ${icon('external')}</a></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">${tr('YOUR LEARNING SPACE','మీ learning space')}<span>/</span><strong>${view==='reader'?tr('One idea at a time','ఒక్కో విషయం'):tr('Keep your curiosity going','నేర్చుకుంటూ ముందుకు వెళ్లండి')}</strong></div><div class="top-actions"><label class="language-label"><span class="sr-only">Learning language</span><select id="language" aria-label="Learning language"><option value="en" ${!te()?'selected':''}>English</option><option value="te" ${te()?'selected':''}>తెలుగు</option></select></label><span class="avatar" aria-label="Personal learning space">K</span></div></header><main id="main">${content}</main><footer class="app-footer"><span>Knowledge Pill</span><span><a href="#settings">${tr('Library settings','Library settings')}</a> · ${tr('Learn it. Try it. Make it yours.','నేర్చుకోండి. ప్రయత్నించండి. గుర్తుంచుకోండి.')}</span></footer></div><div id="toast-root" aria-live="polite"></div>`;}
function metadata(p){return `<span class="pill-topic">${esc(p.topic)}</span><span>${icon('clock')}${p.minutes} ${tr('min + practice','నిమి + అభ్యాసం')}</span>`;}
function card(p,index=0){const bookmarked=state.bookmarks.includes(p.id),review=state.reviews[p.id];return `<article class="pill-card ${p.type==='guide'?'guide-card':''}"><div class="card-meta">${metadata(p)}<button class="icon-button save-button ${bookmarked?'selected':''}" data-save="${esc(p.id)}" aria-label="${bookmarked?'Unsave':'Save'} ${esc(p.title)}" aria-pressed="${bookmarked}">${icon('save')}</button></div><div class="card-category">${p.type==='guide'?`${tr('GUIDED SERIES','GUIDED SERIES')} / 0${p.order}`:p.type==='brief'?tr('EDITORIAL NEWS EXPLAINER','వార్త వివరణ'):p.type==='daily'?esc(p.kind):tr('FOUNDATIONS','FOUNDATIONS')}</div><h3><button class="title-button" data-open="${esc(p.id)}">${esc(p.title)}</button></h3><p class="card-description">${esc(p.summary)}</p><div class="card-bottom"><span>${review?.reviewed_at?`${icon('check')}${tr('Practiced','అభ్యాసం చేశారు')}`:p.type==='foundation'?tr('Evergreen concept','ప్రాథమిక విషయం'):dateLabel(p.date)}</span><button class="read-link" data-open="${esc(p.id)}">${tr('Take this pill','ఈ pill చదవండి')} ${icon('arrow')}</button></div></article>`;}
function home(){const p=latestFor(packets,state.language);const completed=guides.filter(p=>state.reviews[p.id]?.reviewed_at).length;return `<section class="page-heading"><div><p class="eyebrow">${new Intl.DateTimeFormat(te()?'te-IN':'en-US',{weekday:'long',month:'long',day:'numeric'}).format(new Date())}</p><h1 id="page-title" tabindex="-1">${tr('Make AI make sense.','AIను సులభంగా అర్థం చేసుకోండి.')}</h1><p>${tr('A story to understand it. A little practice to make it stick.','అర్థమయ్యే కథ. గుర్తుండే చిన్న అభ్యాసం.')}</p></div><button class="button subtle" data-action="refresh" ${sync.state==='loading'?'disabled':''}>${icon('refresh')}${sync.state==='loading'?tr('Checking…','చూస్తున్నాం…'):tr('Refresh editions','కొత్త editions చూడండి')}</button></section><div class="home-grid"><section class="spotlight"><div class="spotlight-copy"><div class="spotlight-label"><span class="tiny-capsule"></span>${tr('IN FOCUS · JEV & LAYA','ఈసారి · JEV & LAYA')}</div><h2>${tr('Less buzz.<br>More understanding.','కొత్త పేర్ల వెనుక<br>అసలు విషయం.')}</h2><p>${tr('Decision models are having a moment. Understand the idea, the confidence scores and the real tradeoffs in three small pills.','మూడు చిన్న pillsతో decision models, confidence scores, వాటి పరిమితులు తెలుసుకోండి.')}</p><button class="button lime" data-open="decision-models-01">${completed?tr('Revisit the series','మళ్లీ చదవండి'):tr('Start with the story','కథతో మొదలుపెట్టండి')} ${icon('arrow')}</button><span class="spotlight-foot">3 pills · ${tr('English & Telugu','English & తెలుగు')} · ${tr('Sources checked Sep 24','Sources: Sep 24')}</span></div><img class="spotlight-art" src="assets/knowledge-pill-editorial.webp" alt="" width="1536" height="1024" fetchpriority="high"></section><aside class="journey"><div class="journey-top"><span class="section-kicker">${tr('YOUR LEARNING PATH','మీ learning path')}</span>${icon('spark')}</div><h2>${tr('Understand.<br>Then apply.','అర్థం చేసుకోండి.<br>ఉపయోగించండి.')}</h2><ol>${guides.map(g=>`<li><span class="path-number ${state.reviews[g.id]?.reviewed_at?'complete':''}">${state.reviews[g.id]?.reviewed_at?icon('check'):'0'+g.order}</span><button data-open="${g.id}">${esc((te()?['నిర్ణయం ఎలా తీసుకుంటుంది?','Confidence అంటే ఏమిటి?','సరైన model ఎలా ఎంచుకోవాలి?']:['What makes a decision model?','When should you trust a score?','Which model fits your job?'])[g.order-1])}</button></li>`).join('')}</ol><div class="progress-label"><span>${completed} ${tr('of 3 practiced','/ 3 అభ్యాసం చేశారు')}</span><span>${Math.round(completed/3*100)}%</span></div><progress max="3" value="${completed}" aria-label="Series practice progress"></progress></aside></div><section class="daily-section"><div class="section-heading"><div><p class="section-kicker">${tr('TWO WAYS TO KEEP LEARNING','నేర్చుకోవడానికి రెండు మార్గాలు')}</p><h2>${tr('Your latest dose','మీ తాజా pills')}</h2></div><a class="text-link" href="#explore">${tr('Explore all pills','అన్ని pills చూడండి')}${icon('arrow')}</a></div><div class="sync-row">${statusHTML()}${p?`<span class="edition-date">${tr('Edition','Edition')}: ${dateLabel(p.date,true)}</span>`:''}</div>${p&&p.date!==localDay(p.timezone)?`<p class="notice-banner">${tr(`The latest available edition is ${dateLabel(p.date,true)}. It is not today’s news. You can still read it and explore the learning library.`,`అందుబాటులో ఉన్న edition ${dateLabel(p.date,true)}ది. ఇవి ఈరోజు వార్తలు కావు. పాత pill చదవవచ్చు.`)}</p>`:''}${p?`<div class="cards-grid">${card(normalizeDaily(p,'knowledge'))}${p.news.items.length?card(normalizeDaily(p,'news')):briefings.length?card(normalizeBrief(briefings[0])):'<div class="empty-state"><h3>No verified news in this edition</h3><p>Check AI News for explainers and the most recent available roundup.</p><a href="#news" class="text-link">Open AI News →</a></div>'}</div>`:`<div class="empty-state"><h3>${tr('No daily edition available yet','Daily edition ఇంకా లేదు')}</h3><p>${tr('The guided series and foundations are ready to read while we check for new editions.','కొత్త edition కోసం చూస్తుండగా guided series, foundations చదవండి.')}</p><a href="#explore" class="button primary">${tr('Explore pills','Pills చూడండి')}</a></div>`}</section><section><div class="section-heading"><div><p class="section-kicker">${tr('BUILD YOUR UNDERSTANDING','మీ అవగాహన పెంచుకోండి')}</p><h2>${tr('One idea, a little deeper','ఒక్కో విషయాన్ని మరింత లోతుగా')}</h2></div></div><div class="cards-grid three">${guides.map(normalizeGuide).map(card).join('')}</div></section>`;}
function headlinesHTML(){if(!headlines?.items.length)return '';return `<section class="daily-section"><div class="section-heading"><div><p class="section-kicker">${tr('FROM THE ORIGINAL SOURCES','అసలు sources నుంచి')}</p><h2>${tr('On the AI radar','AIలో తాజా విషయాలు')}</h2></div><span class="count-label">${tr('Checked','పరిశీలించిన తేదీ')} ${dateLabel(headlines.checked_at,true)}</span></div><p class="radar-note">${tr('Publisher headlines with original dates. Open a source for its full announcement; explained roundups follow below.','అసలు తేదీలతో publisher headlines. పూర్తి వివరాలకు source తెరవండి. వివరణతో roundups కింద ఉన్నాయి.')}</p>${localDay('UTC',new Date(headlines.checked_at))!==localDay('UTC')?`<p class="notice-banner">${tr('These are the last saved headlines. Check their dates before treating them as current.','ఇవి చివరిగా దాచిన headlines. తాజా విషయాలుగా భావించే ముందు తేదీలు చూడండి.')}</p>`:''}<div class="headline-list">${headlines.items.slice(0,6).map((n,i)=>`<article class="headline-row"><span class="headline-number">${String(i+1).padStart(2,'0')}</span><div><p>${esc(n.publisher)} <span>· ${dateLabel(n.published_at,true)}</span></p><h3><a href="${esc(safeURL(n.url))}" target="_blank" rel="noopener noreferrer">${esc(n.title)} ${icon('external')}</a></h3></div></article>`).join('')}</div></section>`;}
function newsPage(){const latest=latestFor(packets,state.language),items=catalog().filter(p=>p.pillKind==='news'&&p.type==='daily');return `<section class="page-heading"><div><p class="eyebrow">THE AI BRIEFING</p><h1 id="page-title" tabindex="-1">${tr('Know what changed. Understand why.','కొత్తగా ఏం వచ్చింది? ఎందుకు ముఖ్యం?')}</h1><p>${tr('From a new headline to an idea you can explain.','కొత్త వార్తను మీ మాటల్లో వివరించే అవగాహనకు.')}</p></div><button class="button subtle" data-action="refresh" ${sync.state==='loading'?'disabled':''}>${icon('refresh')}${tr('Refresh news','వార్తలు refresh చేయండి')}</button></section><div class="news-intro"><div><span class="section-kicker">${tr('YOUR DAILY READING RITUAL','రోజూ చదివే విధానం')}</span><h2>${tr('What happened → Why it matters → Try it','మార్పు → ఉపయోగం → అభ్యాసం')}</h2><p>${tr('New editions are checked automatically when you open the app. Sources keep their original dates. Recent roundups can include the previous 14 days.','App తెరిచినప్పుడు కొత్త editions check చేస్తుంది. Sources అసలు తేదీలు చూపిస్తాం. Roundupలో గత 14 రోజుల వార్తలు ఉండవచ్చు.')}</p></div>${icon('spark')}</div><div class="sync-row">${statusHTML()}${latest?`<span class="edition-date">Latest edition: ${dateLabel(latest.date,true)}</span>`:''}</div>${latest&&!latest.news.items.length?`<p class="notice-banner">${tr('The latest generated edition did not include verified news. The dated explainer below is ready to read; earlier roundups keep their original dates.','తాజా generated editionలో వార్తలు లేవు. కింద తేదీతో ఉన్న వివరణ చదవండి; పాత roundups అసలు తేదీలతో ఉన్నాయి.')}</p>`:''}${headlinesHTML()}<section class="daily-section"><div class="section-heading"><div><p class="section-kicker">${tr('START HERE','ఇక్కడ మొదలుపెట్టండి')}</p><h2>${tr('A development, explained','ఒక కొత్త విషయం, సులభంగా')}</h2></div></div><div class="cards-grid">${briefings.map(normalizeBrief).map(card).join('')}</div></section><section><div class="section-heading"><div><p class="section-kicker">${tr('DATED DAILY EDITIONS','తేదీతో రోజువారీ editions')}</p><h2>${tr('Your AI news roundups','మీ AI వార్తల roundups')}</h2></div></div>${items.length?`<div class="cards-grid">${items.map(card).join('')}</div>`:`<div class="empty-state"><h3>${tr('The next verified roundup will appear here.','తరువాతి roundup ఇక్కడ కనిపిస్తుంది.')}</h3><p>${tr('Read the explainer above, then follow its deeper-learning link for the full Jev & Laya series.','పై వివరణ చదివి, Jev & Laya seriesతో మరింత తెలుసుకోండి.')}</p></div>`}</section>`;}
function listPage(){const config={explore:[tr('Follow your curiosity.','మీ ఆసక్తితో ముందుకు వెళ్లండి.'),tr('New ideas and the foundations that help them click.','కొత్త విషయాలు, వాటిని అర్థం చేసుకునే పునాదులు.')],saved:[tr('Ideas worth keeping.','మళ్లీ చదవాలనుకున్న విషయాలు.'),tr('Your saved pills, on this device.','ఈ deviceలో దాచిన pills.')],review:[tr('What stayed with you?','ఏం గుర్తుంది?'),tr('Explain an idea in your own words. Come back to anything that needs practice.','మీ మాటల్లో విషయం వివరించండి. అవసరమైనది మళ్లీ చదవండి.')]}[view];let items=catalog();if(view==='saved')items=items.filter(p=>state.bookmarks.includes(p.id));if(view==='review')items=items.filter(p=>state.reviews[p.id]);if(state.topic!=='All topics')items=items.filter(p=>p.topic===state.topic);if(view==='review')items.sort((a,b)=>Date.parse(state.reviews[a.id].due)-Date.parse(state.reviews[b.id].due));return `<section class="page-heading"><div><p class="eyebrow">${view==='explore'?'THE LEARNING LIBRARY':view==='saved'?'YOUR COLLECTION':'RECALL & REVIEW'}</p><h1 id="page-title" tabindex="-1">${config[0]}</h1><p>${config[1]}</p></div><span class="count-label">${items.length} ${tr('pills','pills')}</span></section><div class="filter-row" role="group" aria-label="Filter by topic">${['All topics','Decision models','RAG','Agents','Fine-tuning'].map(t=>`<button class="filter ${state.topic===t?'active':''}" data-topic="${t}" aria-pressed="${state.topic===t}">${esc(t)}</button>`).join('')}</div>${items.length?`<div class="cards-grid ${view==='explore'?'three':''}">${items.map(card).join('')}</div>`:`<div class="empty-state">${icon(view==='saved'?'save':'book')}<h2>${tr(view==='saved'?'Keep your first useful idea here.':view==='review'?'Your first recall starts with a pill.':'No pills for this filter yet.','ఈ విభాగంలో ఇంకా pills లేవు.')}</h2><p>${tr(view==='review'?'Complete the recall step of a pill to schedule your next review.':'Choose a pill from the library to get started.','Library నుంచి pill ఎంచుకుని మొదలుపెట్టండి.')}</p><a class="button primary" href="#today">${tr('Go to daily dose','రోజువారీ pills చూడండి')}</a></div>`}`;}
function sourcesHTML(p){return `<details class="source-panel"><summary>${icon('book')} ${tr('Sources & what to know','Sources, తెలుసుకోవాల్సినవి')} <span>${p.sources.length} ${tr('sources','sources')}</span></summary><div class="source-content">${p.sources.map((s,i)=>`<article class="source-row"><span class="source-number">${i+1}</span><div>${safeURL(s.url)?`<a href="${esc(safeURL(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ${icon('external')}</a>`:`<strong>${esc(s.title)}</strong>`}<p>${esc(s.publisher||'Primary source')} · ${dateLabel(s.date,true)}</p>${s.note?`<p>${esc(s.note)}</p>`:''}</div></article>`).join('')}<p class="evidence-note">${esc(p.evidence_note||'An authored foundation lesson based on the linked source.')}</p>${p.writer_model?`<p class="evidence-note">Writer: ${esc(p.writer_model)}</p>`:''}${te()?'<p class="evidence-note">తెలుగు వివరణ editorial draft. Fluent-speaker review ఇంకా అవసరం.</p>':''}</div></details>`;}
function reader(){const p=current();if(!p)return `<div class="empty-state"><h1 id="page-title" tabindex="-1">${tr('This pill is not available here yet.','ఈ pill ఇంకా అందుబాటులో లేదు.')}</h1><p>${tr('It may belong to another language or an edition that has not loaded.','వేరే భాష లేదా ఇంకా load కాని edition కావచ్చు.')}</p><a href="#explore" class="button primary">Explore pills</a></div>`;const step=state.step,labels=te()?['కథ','విషయం','ఆచరణ','గుర్తు చేసుకోండి']:['The story','The idea','Try it','Make it stick'];let body='';if(step===0){body=`<p class="section-kicker">${p.pillKind==='news'?tr('THE CONTEXT','సందర్భం'):tr('A STORY TO REMEMBER','గుర్తుండే కథ')}</p><h2>${p.pillKind==='news'?tr('Start with what changed.','ముందు మార్పు తెలుసుకోండి.'):tr('Picture this.','ఊహించండి.')}</h2><div class="story-text">${paragraph(p.story)}</div><div class="insight"><span>${icon('spark')}</span><div><strong>${tr('Connect the dots','కథతో విషయం కలపండి')}</strong>${paragraph(p.bridge)}</div></div>${p.pillKind!=='news'?`<p class="fine-print">${tr('An illustrative story or analogy, not a real event or model result.','ఇది ఊహించిన కథ లేదా పోలిక. నిజ సంఘటన లేదా model result కాదు.')}</p>`:''}`;}else if(step===1){body=`<p class="section-kicker">${tr('UNDERSTAND THE IDEA','విషయం అర్థం చేసుకోండి')}</p>${p.concepts.map((c,i)=>`<section class="concept-section"><span class="concept-number">0${i+1}</span><div><h2>${esc(c.heading)}</h2>${paragraph(c.body)}${c.source_ids?`<p class="fine-print">${c.source_ids.map(id=>{const s=p.sources.find(s=>s.id===id);return s?`${esc(s.publisher)} · ${dateLabel(s.date,true)}`:'';}).join(' / ')}</p>`:''}</div></section>`).join('')}<div class="takeaway"><span class="section-kicker">${tr('THE IDEA TO KEEP','గుర్తుంచుకోవాల్సింది')}</span>${paragraph(p.remember)}</div>`;}else if(step===2){body=`<p class="section-kicker">${tr('FROM IDEA TO APPLICATION','ఆలోచన నుంచి ఆచరణకు')}</p><h2>${esc(p.example?.title||tr('Make the idea useful.','విషయాన్ని ఉపయోగించండి.'))}</h2>${p.example?`<div class="example-block">${p.example.before?`<div class="example-line">${esc(p.example.before)}</div><div class="flow-connector">${icon('arrow')}</div><div class="example-line output">${esc(p.example.after)}</div>`:''}${paragraph(p.example.body)}</div>`:''}<div class="exercise-block"><span class="section-kicker">${tr('YOUR TWO-MINUTE EXPERIMENT','మీ రెండు నిమిషాల అభ్యాసం')}</span><h3>${esc(p.exercise.prompt)}</h3><label class="sr-only" for="practice-note">${tr('Your practice notes','మీ practice notes')}</label><textarea id="practice-note" data-note="${esc(p.id)}:practice:${state.language}" rows="5" placeholder="${esc(p.exercise.placeholder||tr('Think it through in your own words…','మీ మాటల్లో రాయండి…'))}">${esc(state.notes[p.id+':practice:'+state.language]||'')}</textarea><p class="fine-print">${tr('Your notes are saved on this device. They are not sent to an AI model.','Notes ఈ deviceలో save అవుతాయి. AI model‌కు పంపబడవు.')}</p><details class="suggestion"><summary>${tr('See one possible approach','ఒక సాధ్యమైన విధానం చూడండి')}</summary>${paragraph(p.exercise.answer)}</details></div>`;}else{const review=state.reviews[p.id];body=`<p class="section-kicker">${tr('A SMALL CHECK, BEFORE YOU GO','వెళ్లే ముందు చిన్న check')}</p><h2>${tr('Can you explain it back?','మీ మాటల్లో చెప్పగలరా?')}</h2>${p.quiz?`<fieldset class="quiz"><legend>${esc(p.quiz.question)}</legend>${p.quiz.options.map((o,i)=>`<label class="quiz-option ${state.quizChoice===i?'chosen':''}"><input type="radio" name="quiz" value="${i}" ${state.quizChoice===i?'checked':''}><span>${esc(o)}</span></label>`).join('')}<button class="button primary" data-action="check-answer">${tr('Check my understanding','నా అవగాహన చూడండి')}</button>${state.showAnswer?`<div class="answer-feedback ${state.quizChoice===p.quiz.correct?'correct':''}" role="status"><strong>${state.quizChoice===p.quiz.correct?tr('You’ve got the key idea.','ముఖ్యమైన విషయం అర్థమైంది.'):tr('A useful distinction to remember.','గుర్తుంచుకోవాల్సిన తేడా.')}</strong><p>${esc(p.quiz.explanation)}</p><p>${tr('Key answer:','సరైన సమాధానం:')} ${esc(p.quiz.options[p.quiz.correct])}</p></div>`:''}</fieldset>`:`<h3>${esc(p.recallQuestion||p.exercise.prompt)}</h3><label class="sr-only" for="recall-note">Your recall answer</label><textarea id="recall-note" data-note="${esc(p.id)}:recall:${state.language}" rows="4" placeholder="${tr('Explain it without looking back…','మళ్లీ చూడకుండా వివరించండి…')}">${esc(state.notes[p.id+':recall:'+state.language]||'')}</textarea><details class="suggestion"><summary>${tr('Reveal the key idea','ముఖ్యమైన విషయం చూడండి')}</summary>${paragraph(p.exercise.answer)}</details>`}<div class="limits"><h3>${tr('Keep these limits in mind','ఈ పరిమితులు గుర్తుంచుకోండి')}</h3><ul>${p.limits.map(l=>`<li>${esc(l)}</li>`).join('')}</ul></div><div class="review-actions"><p>${tr('How did it feel? Choose your next review.','ఎలా అనిపించింది? తరువాతి review ఎంచుకోండి.')}</p><div class="button-row"><button class="button primary" data-review="remembered">${icon('check')}${tr('I can explain it','నేను వివరించగలను')}</button><button class="button" data-review="again">${tr('Practice tomorrow','రేపు మళ్లీ చదవాలి')}</button></div>${review?.due?`<p class="review-confirm" role="status">${tr('Next review','తరువాతి review')}: ${dateLabel(review.due,true)}. ${tr('Self-assessed, not a mastery score.','ఇది మీ స్వీయ అంచనా.')}</p>`:''}</div>`;}
return `<div class="reader-top"><a href="#${view==='saved'?'saved':'explore'}" class="text-link">${icon('arrow','back-arrow')}${tr('Back to pills','Pills వద్దకు')}</a><button class="button subtle ${state.bookmarks.includes(p.id)?'is-saved':''}" data-save="${esc(p.id)}" aria-pressed="${state.bookmarks.includes(p.id)}">${icon('save')}${state.bookmarks.includes(p.id)?tr('Saved','దాచారు'):tr('Save pill','Pill దాచండి')}</button></div><header class="reader-heading"><div class="card-meta">${metadata(p)}<span>${p.type==='daily'?esc(p.kind):p.type==='guide'?`PILL 0${p.order} / 03`:p.type==='brief'?'EDITORIAL NEWS EXPLAINER':'FOUNDATION'}</span></div><h1 id="page-title" tabindex="-1">${esc(p.title)}</h1><p>${esc(p.summary)}</p><span class="reader-date">${p.type==='guide'?tr('Sources checked','Sources పరిశీలించిన తేదీ'):tr('Edition prepared','Edition తయారు చేసిన తేదీ')}: ${dateLabel(p.date,true)}${p.type==='daily'&&p.date!==localDay()?` · ${tr('Archived edition','పాత edition')}`:''}</span></header><div class="reader-layout"><nav class="step-nav" aria-label="Pill steps">${labels.map((l,i)=>`<button class="step-button ${i===step?'active':''}" data-step="${i}" ${i===step?'aria-current="step"':''}><span>0${i+1}</span>${l}</button>`).join('')}<p>${tr('About 5–10 minutes, including practice. Take your time.','Practiceతో కలిపి సుమారు 5–10 నిమిషాలు. నెమ్మదిగా చదవండి.')}</p></nav><div class="reader-main"><article class="reading-card" lang="${state.language}">${body}<div class="reading-controls"><button class="button subtle" data-step="${step-1}" ${step===0?'disabled':''}>${icon('arrow','back-arrow')}${tr('Back','వెనుకకు')}</button><span>${step+1} / 4</span>${step<3?`<button class="button primary" data-step="${step+1}">${labels[step+1]} ${icon('arrow')}</button>`:`<button class="button primary" data-action="next-pill">${tr('Next pill','తరువాతి pill')}${icon('arrow')}</button>`}</div></article>${p.related?`<a class="deeper-link" href="#pill/${encodeURIComponent(p.related)}">${icon('book')}${tr('Go deeper: Jev & Laya in three pills','మరింత తెలుసుకోండి: మూడు Jev & Laya pills')}${icon('arrow')}</a>`:''}${sourcesHTML(p)}</div></div>`;}
function settings(){return `<section class="page-heading"><div><p class="eyebrow">YOUR LIBRARY</p><h1 id="page-title" tabindex="-1">${tr('Keep your learning with you.','మీ learning‌ను భద్రంగా ఉంచుకోండి.')}</h1><p>${tr('Preferences, notes and progress are saved in this browser.','Preferences, notes, progress ఈ browserలో ఉంటాయి.')}</p></div></section><div class="settings-grid"><section class="settings-card"><h2>${tr('Back up your library','మీ library backup')}</h2><p>${tr('Download your saved editions, bookmarks, practice notes and review progress. Import that backup on another device.','దాచిన editions, bookmarks, notes, progress download చేసుకుని మరో deviceలో import చేయవచ్చు.')}</p><button class="button primary" data-action="export">${tr('Export my library','నా library export చేయండి')}</button><label class="import-label" for="library-import">${tr('Import a library backup or daily edition','Library backup లేదా daily edition import చేయండి')}<input id="library-import" type="file" accept="application/json,.json"></label><p class="fine-print">${tr('Only import files you trust. Source links and edition structure are validated; this does not verify every claim.','మీరు నమ్మిన files మాత్రమే import చేయండి. Structure, links check చేస్తాం; ప్రతి నిజాన్ని కాదు.')}</p></section><section class="settings-card"><h2>${tr('Where new pills come from','కొత్త pills ఎలా వస్తాయి')}</h2><p>${tr('Daily editions are generated in the project’s publishing workflow and loaded from its repository. Refresh checks for a completed edition; it does not start paid generation.','Daily editions project publishing workflowలో తయారై repository నుంచి వస్తాయి. Refresh కొత్త edition ఉందో చూస్తుంది; paid generation ప్రారంభించదు.')}</p>${statusHTML()}<button class="button" data-action="refresh" ${sync.state==='loading'?'disabled':''}>${icon('refresh')}${tr('Check for new editions','కొత్త editions చూడండి')}</button><p class="fine-print">${tr('Guided explainers are dated editorial lessons. They are distinct from automatically generated daily drafts.','Guided explainers తేదీతో కూడిన editorial lessons. అవి automatic daily drafts‌కు వేరు.')}</p><a class="text-link" href="https://github.com/DRKREDDY5/Knowledge-Pill/actions/workflows/daily-pills.yml" target="_blank" rel="noopener noreferrer">View publishing status ${icon('external')}</a></section></div>`;}
function render(){document.documentElement.lang=state.language;$('#app').innerHTML=shell(view==='reader'?reader():view==='today'?home():view==='news'?newsPage():view==='settings'?settings():listPage());bindInputs();}
function bindInputs(){$('#language')?.addEventListener('change',e=>{const old=current();state.language=e.target.value;persist();if(old?.type==='daily'){const peer=packets.find(p=>p.date===old.date&&p.topic===old.topic&&p.language===state.language);if(peer){location.hash='#pill/'+encodeURIComponent(peer.id+':'+old.pillKind);}else{toast('No matching edition in this language. Showing the learning library.');nav('explore');}}else{render();}});document.querySelectorAll('[data-note]').forEach(n=>n.addEventListener('input',()=>{state.notes[n.dataset.note]=n.value;persist();}));document.querySelectorAll('input[name="quiz"]').forEach(n=>n.addEventListener('change',()=>{state.quizChoice=Number(n.value);state.showAnswer=false;}));$('#library-import')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>3000000)throw Error('Choose a JSON file smaller than 3 MB.');const data=JSON.parse(await file.text());const imported=importLibrary(data,packets,state,catalog().map(p=>p.id));packets=imported.packets;Object.assign(state,imported.state);savePackets();persist();toast('Library imported. Choose Explore pills to read it.');render();}catch(error){toast(error.message||'This file could not be imported.');}});}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.open){openPill(b.dataset.open);return;}if(b.dataset.save){const id=b.dataset.save;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];persist();const scroll=window.scrollY;render();window.scrollTo({top:scroll,behavior:'instant'});return;}if(b.dataset.topic){state.topic=b.dataset.topic;render();return;}if(b.dataset.step!==undefined){const n=Number(b.dataset.step);if(n>=0&&n<4){state.step=n;state.showAnswer=false;render();$('.reading-card')?.scrollIntoView({behavior:'smooth',block:'start'});}return;}if(b.dataset.review){const p=current();state.reviews[p.id]=scheduleReview(state.reviews[p.id],b.dataset.review==='remembered');persist();render();return;}switch(b.dataset.action){case'refresh':syncNow();break;case'check-answer':if(state.quizChoice===null){toast(tr('Choose an answer first.','ముందు సమాధానం ఎంచుకోండి.'));return;}state.showAnswer=true;render();break;case'next-pill':{const p=current(),items=catalog(),i=items.findIndex(x=>x.id===p.id);openPill(items[(i+1)%items.length].id);break;}case'export':{const blob=new Blob([JSON.stringify({schema_version:2,task:'knowledge_pill_backup',exported_at:new Date().toISOString(),state:{language:state.language,bookmarks:state.bookmarks,reviews:state.reviews,notes:state.notes},packets},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Knowledge_Pill_Library.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}});
async function syncNow(){if(sync.running)return;sync={state:'loading',message:tr('Checking for new editions…','కొత్త editions చూస్తున్నాం…'),running:true};if(view!=='reader')render();const results=await Promise.allSettled([refreshEditions(packets),refreshHeadlines()]);if(results[1].status==='fulfilled'&&(!headlines||Date.parse(results[1].value.checked_at)>=Date.parse(headlines.checked_at)))headlines=results[1].value;try{if(results[0].status!=='fulfilled')throw results[0].reason;packets=results[0].value;savePackets();const p=latestFor(packets,state.language);sync={state:'done',message:p&&p.date===localDay(p.timezone)?tr('Latest edition loaded','తాజా edition లోడ్ అయింది'):tr('Connected · showing the latest published edition','కనెక్ట్ అయింది · తాజా ప్రచురిత edition')};}catch(e){sync={state:'error',message:tr('Could not reach new editions · saved pills are available','కొత్త editions అందలేదు · దాచిన pills చదవవచ్చు')};}if(view!=='reader')render();}
window.addEventListener('hashchange',parseRoute);
async function loadJSON(path){const r=await fetch(path,{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error(path);return r.json();}
const loaded=await Promise.allSettled(['guides.json','lessons.json','editions.json','briefings.json','headlines.json'].map(loadJSON));
if(loaded[0].status==='fulfilled')guides=loaded[0].value;else partial.push('guided series');
try{if(loaded[4].status==='fulfilled')headlines=validateHeadlines(loaded[4].value);}catch{}
if(loaded[3].status==='fulfilled')briefings=loaded[3].value;else partial.push('news explainers');
if(loaded[1].status==='fulfilled')foundations=loaded[1].value;else partial.push('foundations');
try{packets=(Array.isArray(oldDaily.packets)?oldDaily.packets:[]).filter(p=>{try{validateCollection(p);return true;}catch{return false;}});if(loaded[2].status==='fulfilled')packets=mergeEditions(packets,loaded[2].value.packets);}catch{partial.push('bundled editions');}
if(!guides.length&&!briefings.length&&!foundations.length&&!packets.length){$('#app').innerHTML=`<main class="startup"><h1>We couldn’t open your learning library.</h1><p>Please check your connection and reload. Your saved progress has not been removed.</p><button onclick="location.reload()">Try again</button></main>`;}else{parseRoute();if(partial.length)toast('Some sections could not load: '+partial.join(', ')+'. Available pills are ready.');syncNow();}
